import math
import torch

def t(x, grad=False):
    return torch.tensor(x, dtype=torch.float32, device='cpu', requires_grad=grad)

def record(c, r):
    return (t(c), t(r))

def close(a, b):
    torch.testing.assert_close(a, b, rtol=2e-05, atol=2e-06)

def weights(model, d):
    return model(torch.eye(d, dtype=torch.float32)).detach()

def oracle(pairs, epochs, batch_size, lr):
    delta = torch.stack([c - r for (c, r) in pairs])
    w = torch.zeros(delta.shape[1], dtype=torch.float32)

    def evaluate():
        z = (delta @ w).tolist()
        return sum((math.log1p(math.exp(-v)) if v >= 0 else -v + math.log1p(math.exp(v)) for v in z)) / len(z)
    history = [evaluate()]
    for _ in range(epochs):
        for start in range(0, len(pairs), batch_size):
            x = delta[start:start + batch_size]
            gradient = (-torch.sigmoid(-(x @ w))[:, None] * x).mean(0)
            w = w - lr * gradient
        history.append(evaluate())
    return (w, history)

pairs = [record([1.0, 0.0], [0.0, 1.0]),
         record([0.0, 1.0], [-1.0, 0.0]),
         record([0.0, 1.0], [1.0, 0.0]),
         record([0.6, 0.8], [0.0, -1.0]),
         record([1.0, 0.0], [0.0, 1.0])]
before = [(c.clone(), r.clone()) for c, r in pairs]
expected_w, expected_history = oracle(pairs, 3, 2, 0.07)
model, history = train_reward_model(pairs, epochs=3, batch_size=2, lr=0.07)
close(weights(model, 2), expected_w)
close(t(history), t(expected_history))
assert all(torch.equal(c, bc) and torch.equal(r, br)
           for (c, r), (bc, br) in zip(pairs, before))
print("ok")

